public static int categoryIndex(String str) {
    String strNormalTab = normalTab(str);
    if (FilterData.FilterOptionsBean.APP.equals(strNormalTab)) {
        return 1;
    }
    if (FilterData.FilterOptionsBean.GAME.equals(strNormalTab)) {
        return 2;
    }
    if ("update".equals(strNormalTab)) {
        return 3;
    }
    return FilterData.FilterOptionsBean.NOT_INSTALLED.equals(strNormalTab) ? 4 : 0;
}
